import React, { useState, useMemo } from "react";
import { useSearchParams } from "react-router-dom";
import MatchItem from "./MatchItem";

function MatchList({ matches, selectedLeague, orderedLeagues }) {
  const [searchParams] = useSearchParams();
  const searchQuery = searchParams.get("search")?.toLowerCase() || "";

  // По умолчанию null, чтобы видеть все актуальные матчи (архив + будущее)
  const [selectedDate, setSelectedDate] = useState(null);

  const dateOptions = useMemo(() => {
    const dates = [];
    // Кнопки: от 10 дней назад до 7 дней вперед
    for (let i = -10; i <= 7; i++) {
      const d = new Date();
      d.setDate(d.getDate() + i);
      dates.push({
        full: d.toISOString().split("T")[0],
        day: d.getDate(),
        weekday: d.toLocaleDateString("ru-RU", { weekday: "short" }),
      });
    }
    return dates;
  }, []);

  const filteredMatches = useMemo(() => {
    // 1. Убираем из списка матчи без команд (защита от краша)
    let result = matches.filter((m) => m && m.homeTeam && m.awayTeam);

    // 2. Фильтр поиска
    if (searchQuery) {
      return result.filter(
        (m) =>
          m.homeTeam.name.toLowerCase().includes(searchQuery) ||
          m.awayTeam.name.toLowerCase().includes(searchQuery) ||
          (m.homeTeam.name_ru &&
            m.homeTeam.name_ru.toLowerCase().includes(searchQuery)),
      );
    }

    // 3. Фильтр лиги
    if (selectedLeague) {
      result = result.filter((m) => m.league === selectedLeague);
    }

    // 4. Фильтр даты (сравнение только YYYY-MM-DD)
    if (selectedDate) {
      result = result.filter(
        (m) => m.utcDate.substring(0, 10) === selectedDate,
      );
    }

    return result;
  }, [matches, selectedLeague, selectedDate, searchQuery]);

  const groupedMatches = useMemo(() => {
    const groups = {};
    filteredMatches.forEach((match) => {
      const leagueCode = match.league || "Other";
      if (!groups[leagueCode]) {
        const leagueObj = orderedLeagues.find(
          (l) => l.code === leagueCode || l.name === leagueCode,
        );
        groups[leagueCode] = {
          name: leagueObj ? leagueObj.name : leagueCode,
          order: leagueObj ? orderedLeagues.indexOf(leagueObj) : 999,
          matches: [],
        };
      }
      groups[leagueCode].matches.push(match);
    });
    return Object.entries(groups).sort((a, b) => a[1].order - b[1].order);
  }, [filteredMatches, orderedLeagues]);

  const formatErrorDate = (dateStr) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split("-");
    return `${d}-${m}-${y}`;
  };

  if (!matches || matches.length === 0) {
    return (
      <div className="text-center py-20 text-gray-500 uppercase font-black tracking-widest animate-pulse">
        Загрузка данных из БД...
      </div>
    );
  }

  return (
    <div className="w-full">
      {!searchQuery && (
        <div className="flex items-center gap-1 md:gap-2 mb-10 mt-0 bg-gray-900/40 p-2 rounded-b-2xl border-x border-b border-gray-800 w-full overflow-x-auto no-scrollbar">
          <button
            onClick={() => setSelectedDate(null)}
            className={`flex-shrink-0 px-6 h-14 rounded-xl font-black text-[10px] uppercase transition-all ${selectedDate === null ? "bg-red-600 text-white shadow-lg" : "bg-gray-800 text-gray-500 hover:bg-gray-700"}`}
          >
            ВСЕ
          </button>
          {dateOptions.map((d) => (
            <button
              key={d.full}
              onClick={() => setSelectedDate(d.full)}
              className={`flex-shrink-0 min-w-[60px] flex flex-col items-center justify-center h-14 rounded-xl transition-all ${selectedDate === d.full ? "bg-red-600 text-white shadow-lg" : "bg-gray-800 text-gray-500 hover:bg-gray-700"}`}
            >
              <span className="text-[8px] font-black uppercase mb-1 leading-none">
                {d.weekday}
              </span>
              <span className="text-base font-black leading-none">{d.day}</span>
            </button>
          ))}
          <div className="relative flex-shrink-0 ml-1">
            <input
              type="date"
              className="absolute inset-0 opacity-0 cursor-pointer z-10"
              onChange={(e) => setSelectedDate(e.target.value)}
            />
            <button
              className={`w-12 h-14 flex items-center justify-center rounded-xl transition-colors ${selectedDate && !dateOptions.find((o) => o.full === selectedDate) ? "bg-red-600 text-white" : "bg-gray-800 text-gray-500"}`}
            >
              <svg
                className="w-5 h-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                />
              </svg>
            </button>
          </div>
        </div>
      )}

      {groupedMatches.length === 0 ? (
        <div className="text-center py-20 bg-gray-900/20 rounded-3xl border border-gray-800/50 px-6 animate-in fade-in duration-500">
          <h3 className="text-white font-black uppercase tracking-tighter text-lg mb-2">
            {searchQuery
              ? `Команда "${searchQuery}" не найдена`
              : `Матчей на ${formatErrorDate(selectedDate)} не найдено`}
          </h3>
          <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest leading-relaxed">
            Попробуйте нажать кнопку "ВСЕ" <br /> или воспользуйтесь календарем.
          </p>
        </div>
      ) : (
        groupedMatches.map(([code, league]) => (
          <div key={code} className="mb-14">
            <div className="flex flex-col items-center mb-8">
              <h2 className="text-2xl font-black text-white uppercase tracking-tighter italic">
                {league.name}
              </h2>
              <div className="w-16 h-1 bg-red-600 mt-2 rounded-full opacity-40 shadow-[0_0_10px_red]"></div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6">
              {league.matches.map((match) => (
                <MatchItem key={match.id} match={match} />
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

export default MatchList;
